"""Download a Zoom cloud recording via yt-dlp."""

import subprocess
import sys


URL = "https://illinois.zoom.us/rec/share/t0JfmP-JPsGRaab3D6g9uvR8sv7lyTBVgG63gPXWDDh3F23Rzc8dr1DCAVZlMsom.UW4s4DVz5L6TgxRF"
PASSCODE = ""  # Set this if the recording is passcode-protected


def main():
    try:
        subprocess.run(["yt-dlp", "--version"], capture_output=True, check=True)
    except (subprocess.CalledProcessError, FileNotFoundError):
        print("yt-dlp not found. Install it with: pip install yt-dlp")
        sys.exit(1)

    cmd = ["yt-dlp", "--no-playlist", "-o", "%(title)s.%(ext)s", URL]

    if PASSCODE:
        cmd += ["--video-password", PASSCODE]

    print(f"Downloading: {URL}")
    result = subprocess.run(cmd)
    sys.exit(result.returncode)


if __name__ == "__main__":
    main()

